52	export function parseBotAvatar(
53	  rawColor: string,
54	  _identity?: string,
55	): {
56	  color: string;
57	  shapeIndex?: number;
58	  isImage: boolean;
59	  imageUrl?: string;
60	} {
61	  if (!rawColor) return { color: "#F97316", isImage: false };
62	  // Only data: image URLs are rendered. Arbitrary http(s)/blob values in `color`
63	  // must not become <img src> (SSRF / tracking when other members view the bot).
64	  if (rawColor.startsWith("data:image/")) {
65	    return { color: "#F97316", isImage: true, imageUrl: rawColor };
66	  }
67	  if (rawColor.includes("::shape_")) {
68	    const parts = rawColor.split("::shape_");
69	    const rawShapeIdx = parts[1] ?? "0";
70	    const parsedShapeIdx = /^\d+$/.test(rawShapeIdx) ? Number(rawShapeIdx) : 0;
71	    const shapeIdx = Number.isSafeInteger(parsedShapeIdx) ? parsedShapeIdx : 0;
72	    return {
73	      color: parts[0] || "#F97316",
74	      shapeIndex: shapeIdx % SHIPPED_SHAPE_KEYS.length,
75	      isImage: false,
76	    };
77	  }
78	  return { color: rawColor, isImage: false };
79	}
