467	              values={`${shapeA};${shapeB};${shapeA}`}
468	              dur={duration}
469	              repeatCount="indefinite"
470	            />
471	          ) : null}
472	        </path>
473	      ))}
474	      <g transform={`rotate(${(seed % 9) - 4})`}>
475	        {(["idle", "working"] as const).map((mode) => (
476	          <g
477	            key={mode}
478	            className={`rakazo-organic-avatar-eyes rakazo-organic-avatar-eyes-${mode}`}
479	            fill={tokens.background}
480	          >
481	            <rect x="-14" y="-12" width="7" height="24" rx="3.5" />
482	            <rect x="7" y="-12" width="7" height="24" rx="3.5" />
483	          </g>
484	        ))}
485	      </g>
486	    </svg>
487	  );
488	}
