490	const reducedMotionMedia = "(prefers-reduced-motion: reduce)";
491	
492	function reducedMotionSnapshot(): boolean {
493	  return window.matchMedia(reducedMotionMedia).matches;
494	}
495	
496	function subscribeToReducedMotion(onChange: () => void): () => void {
497	  const media = window.matchMedia(reducedMotionMedia);
498	  media.addEventListener("change", onChange);
499	  return () => media.removeEventListener("change", onChange);
500	}
