1	import { resolvePersonaColorDef, SHIPPED_BOT_AVATAR_SHAPE_KEYS, shippedHash } from "@/lib/avatar";
2	
3	/**
4	 * BotAvatar's `color` prop is rakazo's stored avatar value: "<hex>" or "<hex>::shape_<n>".
5	 * An empty value falls back to one fixed orange (so every agent looked the same), which is
6	 * why each agent gets an explicit value here: a curated color + mascot shape for our known
7	 * agents, and a value derived from the id for anything else.
8	 */
9	const CURATED: Record<string, string> = {
10	  assistant: "#8B5CF6::shape_0", // violet hex
11	  "market-researcher": "#06B6D4::shape_4", // cyan pebble
12	  cfo: "#10B981::shape_2", // green squircle
13	  github: "#64748B::shape_1", // slate wedge
14	  neatlogs: "#F43F5E::shape_3", // rose tablet
15	  "customer-success": "#F59E0B::shape_5", // amber blob
16	  legal: "#6366F1::shape_7", // indigo cloud
17	  hr: "#EC4899::shape_6", // pink teardrop
18	  marketing: "#F97316::shape_4", // orange pebble
19	  sales: "#14B8A6::shape_0", // teal hex
20	};
21	
22	export function agentAvatarValue(agentId: string): string {
23	  const curated = CURATED[agentId];
24	  if (curated) return curated;
25	  const color = resolvePersonaColorDef(agentId).hex;
26	  const shape = shippedHash(agentId) % SHIPPED_BOT_AVATAR_SHAPE_KEYS.length;
27	  return `${color}::shape_${shape}`;
28	}
