// Modified from rakazo (Apache-2.0), github.com/elie222/rakazo@912c977
import { createContext, type ReactNode, useContext } from "react";

export type AvatarStyle = "robot" | "organic";

const AvatarStyleContext = createContext<AvatarStyle>("robot");

export function AvatarStyleProvider({
  children,
  value,
}: {
  children: ReactNode;
  value: AvatarStyle;
}) {
  return <AvatarStyleContext value={value}>{children}</AvatarStyleContext>;
}

export function useAvatarStyle(): AvatarStyle {
  return useContext(AvatarStyleContext);
}
// Modified from rakazo (Apache-2.0), github.com/elie222/rakazo@912c977
import {
  type AppearancePreference,
  persistAppearancePreference,
  type ResolvedAppearance,
  resolveAppearance,
  resolveAppearancePreference,
  tokensForAppearance,
} from "@/lib/tokens";

export type { AppearancePreference, ResolvedAppearance };

const THEME_COLOR_META = 'meta[name="theme-color"]';

export function readSystemAppearance(
  media: Pick<MediaQueryList, "matches"> | null = typeof window !== "undefined"
    ? window.matchMedia("(prefers-color-scheme: light)")
    : null,
): ResolvedAppearance {
  return media?.matches ? "light" : "dark";
}

export function applyResolvedAppearance(
  appearance: ResolvedAppearance,
  root: HTMLElement | null = typeof document !== "undefined" ? document.documentElement : null,
): void {
  if (!root) return;
  root.dataset.theme = appearance;
  root.style.colorScheme = appearance;
  if (typeof document === "undefined") return;
  const meta = document.querySelector(THEME_COLOR_META);
  if (meta) {
    meta.setAttribute("content", tokensForAppearance(appearance).background);
  }
}

export function applyUiAppearance(
  preference: AppearancePreference = resolveAppearancePreference(),
  system: ResolvedAppearance = readSystemAppearance(),
): ResolvedAppearance {
  const resolved = resolveAppearance(preference, system);
  applyResolvedAppearance(resolved);
  return resolved;
}

export function setUiAppearance(preference: AppearancePreference): ResolvedAppearance {
  persistAppearancePreference(preference);
  return applyUiAppearance(preference);
}

export function getUiAppearancePreference(): AppearancePreference {
  return resolveAppearancePreference();
}

/** Keep `data-theme` in sync when the OS scheme changes and preference is System. */
export function watchSystemAppearance(
  onChange: (system: ResolvedAppearance) => void = () => {
    if (resolveAppearancePreference() === "system") applyUiAppearance("system");
  },
): () => void {
import { LazyMotion, MotionConfig } from "motion/react";
import { StrictMode, useEffect } from "react";
import { createRoot } from "react-dom/client";
import { App } from "./App";
import { applyResolvedAppearance, applyUiAppearance, watchSystemAppearance } from "./lib/appearance";
import { loadMotionFeatures } from "./lib/motion";
import "./styles.css";

// ?theme=light|dark forces a theme for this load only (matches the pre-paint script in index.html).
const forcedTheme = new URLSearchParams(window.location.search).get("theme");
const themeForced = forcedTheme === "light" || forcedTheme === "dark";
if (themeForced) applyResolvedAppearance(forcedTheme);
else applyUiAppearance();

function AppearanceSync() {
  useEffect(() => (themeForced ? undefined : watchSystemAppearance()), []);
  return null;
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <AppearanceSync />
    {/* reducedMotion="user": with prefers-reduced-motion, transforms and layout moves are dropped (opacity stays). */}
    <MotionConfig reducedMotion="user">
      {/* strict: only the lean `m.*` components are allowed; features load lazily. */}
      <LazyMotion features={loadMotionFeatures} strict>
        <App />
      </LazyMotion>
    </MotionConfig>
  </StrictMode>,
);

