host.id = "__avatar_preview";
host.style.cssText = "position:fixed;inset:0;z-index:99999;overflow:auto;background:var(--background, #fff);color:var(--foreground,#000)";
document.body.appendChild(host);
createRoot(host).render(
  <div>
    <Row id="neatlogs" />
    <Row id="neatlogs" status="running" />
    <Row id="assistant" />
    <Row id="assistant" status="running" />
  </div>,
);
